public class Main {
    public static void main(String[] args) {
        LocalDate hariIni = LocalDate.of(2026, 10, 30);
        LocalDate jatuhTempo = LocalDate.of(2026, 10, 28);
        LocalDate promo = LocalDate.of(2026, 11, 11);

        System.out.println(hariIni.isAfter(jatuhTempo));
        System.out.println(hariIni.isBefore(promo));
        System.out.println(jatuhTempo.isEqual(LocalDate.parse("2026-10-28")));
        System.out.println(promo.compareTo(hariIni) > 0);
    }
}

