import java.time.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        LocalDate hariIni = LocalDate.of(2026, 10, 30);
        List<LocalDate> tagihan = new ArrayList<>(Arrays.asList(
                LocalDate.of(2026, 10, 29),
                LocalDate.of(2026, 11, 5),
                LocalDate.of(2026, 10, 20)));
        Collections.sort(tagihan);
        for (LocalDate t : tagihan) {
            if (hariIni.isAfter(t)) {
                System.out.println(t + " terlambat");
            }
        }
    }
}

